/*
 * Open-source licences: the catalogue generated by the build lists every
 * packaged library with a version, developers and licences, sorted by name,
 * with the full text of each licence used; the screen lists, searches and
 * opens a library with its links and licence text. Screenshots go to
 * build/outputs/roborazzi.
 * Copyright (C) 2026 FebriCahyaa
 */
package com.zairenkai.app.ui.legal

import androidx.activity.ComponentActivity
import androidx.compose.ui.test.assertIsDisplayed
import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.compose.ui.test.onAllNodesWithText
import androidx.compose.ui.test.onNodeWithText
import androidx.compose.ui.test.onRoot
import androidx.compose.ui.test.performClick
import androidx.compose.ui.test.performTextInput
import com.github.takahirom.roborazzi.captureRoboImage
import com.zairenkai.app.R
import com.zairenkai.app.shotPath
import com.zairenkai.app.ui.theme.ZairenkaiTheme
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import org.robolectric.annotation.GraphicsMode

@RunWith(RobolectricTestRunner::class)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
@Config(sdk = [35], qualifiers = "w411dp-h891dp-xxhdpi", application = android.app.Application::class)
class OssLicensesTest {
    @get:Rule val rule = createAndroidComposeRule<ComponentActivity>()

    private val catalog by lazy { OssCatalog.load(rule.activity) }

    @Test
    fun catalogueIsCompleteAndSorted() {
        val libs = catalog.libraries
        assertTrue("libraries: ${libs.size}", libs.size > 100)
        assertEquals(libs.map { it.name.lowercase() }.sorted(), libs.map { it.name.lowercase() })
        libs.forEach { l ->
            assertTrue("${l.id} has a version", l.version.isNotBlank())
            assertTrue("${l.id} has a licence", l.licenses.isNotEmpty())
            l.licenses.forEach { assertTrue("${l.id}: text for ${it.spdx}", catalog.texts[it.spdx]?.isNotBlank() == true) }
        }
        assertTrue(libs.any { it.id == "androidx.compose.material3:material3" })
        assertTrue(libs.any { it.id == "fonts:google-sans-flex" && it.licenses.single().spdx == "OFL-1.1" })
        assertTrue(catalog.texts.getValue("Apache-2.0").contains("TERMS AND CONDITIONS FOR USE, REPRODUCTION, AND DISTRIBUTION"))
    }

    @Test
    fun licenceTextFlowsByParagraph() {
        val flowed = reflowLicense("TERMS AND CONDITIONS FOR USE,\n   REPRODUCTION, AND DISTRIBUTION\n\n   1. Definitions.\n")
        assertEquals("TERMS AND CONDITIONS FOR USE, REPRODUCTION, AND DISTRIBUTION\n\n1. Definitions.", flowed)
    }

    @Test
    fun searchFiltersByNameDeveloperAndLicence() {
        assertTrue(catalog.filter("lottie").all { it.name.contains("Lottie", true) || it.id.contains("lottie") })
        assertTrue(catalog.filter("JetBrains").isNotEmpty())
        assertEquals(catalog.libraries.size, catalog.filter("").size)
        assertTrue(catalog.filter("zzzz-no-such-library").isEmpty())
    }

    @Test
    fun listAndDetailSheet() {
        rule.setContent { ZairenkaiTheme(themeMode = "light", dynamicColor = false) { OssLicensesContent(catalog) } }
        rule.onRoot().captureRoboImage(shotPath("licenses_list_light.png"))
        val first = catalog.libraries.first()
        rule.onAllNodesWithText(first.name)[0].performClick()
        rule.mainClock.advanceTimeBy(600)
        rule.onNodeWithText(rule.activity.getString(R.string.oss_view_license)).assertIsDisplayed().performClick()
        rule.mainClock.advanceTimeBy(600)
        rule.onNodeWithText(catalog.libraries.first().licenses.first().name).assertIsDisplayed()
        rule.onRoot().captureRoboImage(shotPath("licenses_detail_light.png"))
    }

    @Test
    fun listDarkSearched() {
        rule.setContent {
            ZairenkaiTheme(themeMode = "dark", dynamicColor = false) {
                androidx.compose.material3.Surface(color = androidx.compose.material3.MaterialTheme.colorScheme.surface) { OssLicensesContent(catalog) }
            }
        }
        rule.onNodeWithText(rule.activity.getString(R.string.oss_search)).performTextInput("kotlin")
        rule.waitForIdle()
        rule.onRoot().captureRoboImage(shotPath("licenses_search_dark.png"))
    }
}
